function SlotIcon<Slot extends ComponentIconSlotName>({
  slot,
  state,
  fallback,
  color,
}: Omit<ComponentIconProps<Slot>, 'content'>): ReactNode {
  const {icon, variant, size} = useComponentIcon(slot, state, fallback);
  if (icon == null) {
    return null;
  }
